function IS_INTERLEAVED(F, G, delta):
    if delta < 0: return False
    carrier <- { sigma : sigma in dom(F) and sigma in dom(G) }
    if carrier is empty: return False           # no interleaving exists
    for sigma in carrier:
        if |F.weight[sigma] - G.weight[sigma]| > delta: return False
    return True

function INTERLEAVING_DISTANCE(F, G):
    carrier <- { sigma : sigma in dom(F) and sigma in dom(G) }
    if carrier is empty: return +infinity
    return max over sigma in carrier of |F.weight[sigma] - G.weight[sigma]|
    # the max is attained: the infimum over slacks is reached

function VR_FILTRATION(d, n, max_dim):
    weight[empty] <- 0
    for k in 1..max_dim:
        for each k-subset sigma of {0,...,n-1}:
            weight[sigma] <- max(0, max_{x,y in sigma} d(x,y))
    return weight

